#include <algorithm>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <string>

using namespace std::literals;
namespace ranges = std::ranges;

int main() {
    std::cout << "[raw] [" << INT8_MIN << ',' << INT8_MAX
              << "] "
                 "[0"
              << ',' << UINT8_MAX << "]\n";
    for (int const v : {-129, -128, -1, 0, 42, 127, 128, 255, 256})
        std::cout << std::setw(4) << v << std::setw(11)
                  << ranges::clamp(v, INT8_MIN, INT8_MAX) << std::setw(8)
                  << ranges::clamp(v, 0, UINT8_MAX) << '\n';
    std::cout << std::string(23, '-') << '\n';

    // Projection function
    const auto stoi = [](std::string s) { return std::stoi(s); };

    // Same as above, but with strings
    for (std::string const v :
        {"-129", "-128", "-1", "0", "42", "127", "128", "255", "256"})
        std::cout << std::setw(4) << v << std::setw(11)
                  << ranges::clamp(v, "-128"s, "127"s, {}, stoi) << std::setw(8)
                  << ranges::clamp(v, "0"s, "255"s, {}, stoi) << '\n';
}
